import{z as A,x as B,o as E,c as d,q as r,j as n,D as e,d as t,s as l,S as s,b as i}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"生产函数估计的深化","description":"","frontmatter":{"title":"生产函数估计的深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/se-production-deep.md","filePath":"econ/se-production-deep.md","lastUpdated":1791063341000}'),p={name:"econ/se-production-deep.md"};function m(c,a,h,_,C,D){const o=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="生产函数估计的深化" tabindex="-1">生产函数估计的深化 <a class="header-anchor" href="#生产函数估计的深化" aria-label="Permalink to &quot;生产函数估计的深化&quot;">​</a></h1><div class="epigraph"><p>生产率不只是回归的残差：它是厂商的私有信息，是逐年滚动的状态，也是退出与出口的门票；估准了它的动态，弹性、加成与再配置才是一套账。</p><footer>—— 据 Olley and Pakes, Econometrica 1996；De Loecker and Warzynski, AER 2012 整理</footer></div><p><a href="/econ/se-dynamic-discrete-choice">上一课</a>把前向选择写成可估结构。生产函数里的 \\(\\omega\\) 正是这样一个状态：厂商看见它再选投入，太低的还会退出——<a href="/econ/production-function-estimation">主干课</a>已经给了 OP/LP/ACF 的最小版本：代理单调、反演、创新矩。本课深化三处：第二阶段的动态写全、退出修正是动态选择问题而非修补、从弹性走到加成的最后一步。出口参与这个选择问题也一并归位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干课把 \\(\\omega\\) 当「要赶出去的遗漏变量」；深化的立场是把它当对象本身。\\(y_{it}=\\beta_k k_{it}+\\beta_l l_{it}+\\omega_{it}+\\varepsilon_{it}\\)，若 \\(\\omega\\) 服从 \\(\\omega_{it}=g(\\omega_{i,t-1})+\\xi_{it}\\)，那么 \\(\\xi\\) 才是新信息，矩条件是 \\(\\mathbb{E}[\\xi_{it}\\mid\\text{过去的资本与投入}]=0\\)——比主干课的第二阶段更精确，还允许生产率均值回归与异方差冲击。缺口在：退出不是样本麻烦，是经济行为；低 \\(\\omega\\) 厂商退出使样本里的 \\(\\omega\\) 被截断，修正要写成参与概率（上一课的装置）。而产出若是收入而非数量，价格随质量与市场势力变化，估出的「弹性」混着需求曲率。</p><p><span class="marginnote">直觉类比：\\(\\omega\\) 像厂商的「体质」，老板自己知道、外人看不见。体质好的多招人多投资、体质差的关门——所以数据里看到的厂商构成，已经是体质筛过一遍的结果。把回归残差当体质，等于只给幸存者做了体检。</span></p><h3 id="从弹性到加成" tabindex="-1">从弹性到加成 <a class="header-anchor" href="#从弹性到加成" aria-label="Permalink to &quot;从弹性到加成&quot;">​</a></h3><p>De Loecker–Warzynski 把可变投入的一阶条件整理成</p> \\[\\mu_{it} \\;=\\; \\theta^{l}_{it}\\big/\\alpha^{l}_{it}, \\]<p>\\(\\theta^l\\) 是产出对劳动的弹性（生产函数估计给出），\\(\\alpha^l\\) 是劳动支出份额（会计数据给出）。于是生产函数的产物不止 TFP：加成有了厂级时间序列。前提是劳动可灵活调整、无调整成本，且价格差异已被处理——每条前提都能坏。</p><p><span class="marginnote">数字实例：估出劳动弹性 \\(\\theta^l=0.6\\)，会计数据显示劳动支出份额 \\(\\alpha^l=0.3\\)，则加成 \\(\\mu=0.6/0.3=2\\)——价格是边际成本的两倍。若存在解雇成本、劳动其实不灵活，这个「2」就系统性偏高，市场势力被高估。</span></p><p><span class="marginnote">Olley–Pakes 1996 的再配置分解：行业生产率变化 = 厂内成长 + 存活者间份额转移 + 进入 − 退出。宏观「全要素生产率提高」可能是厂内进步，也可能只是低效厂关门，政策含义完全不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>完整写法分四步。第一步：声明时序——资本预定，代理变量（投资或中间投入）在 \\(\\omega\\) 实现后选择。第二步：非参数第一阶段，把 \\(\\omega\\) 的现值与退出概率一并收进函数；退出概率正是上一课动态选择里的 CCP。第三步：第二阶段用 \\(\\xi\\) 对滞后状态的矩估 \\(\\beta_k\\)，同时估转移函数 \\(g\\) 与退出机制参数。第四步：把弹性代进加成公式，或把 \\(\\omega\\) 的分布送进 OP 再配置分解。</p><p>收入与数量的分岔是老坑：只有收入数据时需同时估需求（或控制价格），否则 \\(\\beta_l\\) 吸了加成差异。<a href="/econ/se-dynamic-discrete-choice">上一课</a>的反演思想在出口参与处复用：厂商看见预期出口收益再选择进入，把它当外生切换会高估「出口学习效应」。</p>',15)),(E(),n(s,null,{default:e(()=>[l(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20TIMING%5B%22%E6%97%B6%E5%BA%8F%E4%B8%8E%E4%BB%A3%E7%90%86%E9%80%89%E6%8B%A9%22%5D%20--%3E%20INV%5B%22%E9%9D%9E%E5%8F%82%E6%95%B0%E5%8F%8D%E6%BC%94%20%CF%89%20%E4%B8%8E%E9%80%80%E5%87%BA%E6%A6%82%E7%8E%87%22%5D%0A%20%20EXIT%5B%22%E9%80%80%E5%87%BA%20%3D%20%E5%8A%A8%E6%80%81%E9%80%89%E6%8B%A9%22%5D%20--%3E%20INV%0A%20%20INV%20--%3E%20DYN%5B%22%CE%BE%20%E7%9A%84%E5%8A%A8%E6%80%81%E7%9F%A9%20%2B%20%E8%BD%AC%E7%A7%BB%20g%22%5D%0A%20%20DYN%20--%3E%20ELAS%5B%22%E5%BC%B9%E6%80%A7%20%CE%B2%22%5D%0A%20%20ELAS%20--%3E%20MU%5B%22%E5%8A%A0%E6%88%90%20%CE%BC%20%3D%20%CE%B8%2F%CE%B1%22%5D%0A%20%20DYN%20--%3E%20DEC%5B%22OP%20%E5%86%8D%E9%85%8D%E7%BD%AE%E5%88%86%E8%A7%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[t("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"机制仍是信息时序，但深化的位置在「谁在选择」。主干课让代理变量吸收选择；深化课承认选择是多层的——投入选择、退出选择、出口选择——且都基于 \\(\\omega\\)。每层选择对应一个反演或一个参与概率，估错一层，弹性就混进一截选择效应。ACF 的警告在这里更尖锐：两支灵活投入不能同时从同一阶段拆出两个弹性，时序声明是识别而非文书。",-1)),(E(),n(s,null,{default:e(()=>[l(o,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E7%94%9F%E4%BA%A7%E7%8E%87%20%CF%89%20%E5%AE%9E%E7%8E%B0%E5%90%8E%2C%20%E5%8E%82%E5%95%86%E4%BE%9D%E6%AC%A1%E5%81%9A%E4%B8%89%E5%B1%82%E9%80%89%E6%8B%A9%22%5D%20--%3E%20IN%5B%22%E6%8A%95%E5%85%A5%E9%80%89%E6%8B%A9%EF%BC%9A%E4%BB%A3%E7%90%86%E5%8F%98%E9%87%8F%E5%8F%8D%E6%BC%94%22%5D%0A%20%20W%20--%3E%20EX%5B%22%E9%80%80%E5%87%BA%E9%80%89%E6%8B%A9%EF%BC%9A%E5%8F%82%E4%B8%8E%E6%A6%82%E7%8E%87%20CCP%22%5D%0A%20%20W%20--%3E%20EPT%5B%22%E5%87%BA%E5%8F%A3%E9%80%89%E6%8B%A9%EF%BC%9A%E9%A2%84%E6%9C%9F%E6%94%B6%E7%9B%8A%E5%8F%8D%E6%BC%94%22%5D%0A%20%20IN%20--%3E%20BETA%5B%22%E5%BC%B9%E6%80%A7%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20EX%20--%3E%20BETA%0A%20%20EPT%20--%3E%20BETA%0A%20%20BETA%20--%3E%20ERR%5B%22%E6%BC%8F%E6%8E%89%E4%B8%80%E5%B1%82%2C%20%E5%BC%B9%E6%80%A7%E6%B7%B7%E8%BF%9B%E4%B8%80%E6%88%AA%E9%80%89%E6%8B%A9%E6%95%88%E5%BA%94%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>转移函数 \\(g\\) 让「生产率的持续性」可检验：若 \\(g\\) 的斜率接近一，冲击是持久性的，投资与进入行为会放大它；若强均值回归，份额再配置主导。同一套矩既估弹性又估动态，这是把 \\(\\omega\\) 当对象的回报。</p><p><span class="marginnote">常见误区：初学者容易把「出口企业生产率更高」读成「出口让企业变强」。若体质好的企业先选择出口，把外生切换当因果就会把选择效应读成学习效应——修正办法是给出口决定单独建一个参与概率。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重算宏观 TFP 核算，也不把加成当成市场势力的完整度量——固定成本与进入壁垒不在 \\(\\mu\\) 里。Gandhi–Navarro–Rivers 的识别质疑（主干课提过）没有消失：某些完全竞争设定下弹性识别变薄，要靠需求边或风险价格补。加成公式的「劳动可灵活调整」若不成立（解雇成本存在），\\(\\mu\\) 系统性偏。质量调整与数量错测的坑照旧。</p><p>后课默认：厂级生产函数先写多层选择与时序；退出与出口是动态选择问题；收入数据要配需求或价格控制；弹性之外顺手报加成。下一课拍卖：对象换回博弈场，出价反演估值。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\omega\\) 是对象：转移 \\(g\\) 与创新 \\(\\xi\\) 的矩让生产率动态可估。</li><li>退出与出口写成参与概率（CCP），不是样本清洗。</li><li>De Loecker–Warzynski：加成 = 弹性 ÷ 支出份额，前提是劳动灵活调整。</li><li>OP 分解把行业 TFP 变化拆成厂内、再配置、进入、退出。</li><li>收入数据混入价格差异，须配需求边。</li><li>出处：Olley and Pakes, <em>Econometrica</em> 1996；Levinsohn and Petrin, <em>RES</em> 2003；Ackerberg, Caves and Frazer, <em>Econometrica</em> 2015；De Loecker and Warzynski, <em>AER</em> 2012。</li></ul>',7))])}const P=A(p,[["render",m]]);export{g as __pageData,P as default};
